import torch, torch.nn.functional as F

def gen_ppl(logits_ext, targets):
    nll = F.cross_entropy(logits_ext.view(-1, logits_ext.size(-1)), targets.view(-1))
    return torch.exp(nll)

import torch

def rectified_flow_loss(v_net, x0, x1):
    t = torch.rand(x0.size(0), *([1] * (x0.dim() - 1)), device=x0.device)
    x_t = (1 - t) * x0 + t * x1
    return ((v_net(x_t, t.squeeze(-1)) - (x1 - x0)) ** 2).mean()
